int sumOdd(int n) {
    int s = 0;
    for (int i = 1; i <= n; ++i) {
        if (i % 2 == 0) continue;
        s += i;
    }
    return s;
}

int choose(int x) {
    int y = 0;
    switch (x) {
        case 1: y += 1; [[fallthrough]];
        case 2: y += 2; break;
        default: y = 9;
    }
    return y;
}
